-- ============================================================
--  Telco Customer Churn - Data Warehouse (Star Schema)
--  Target RDBMS : Microsoft SQL Server
--  Grain        : One row per customer (end-of-period snapshot)
--  Generated    : 2026-05-11
-- ============================================================

USE master;
GO

IF DB_ID('TelcoChurnDW') IS NOT NULL
BEGIN
    ALTER DATABASE TelcoChurnDW SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE TelcoChurnDW;
END
GO

CREATE DATABASE TelcoChurnDW COLLATE Latin1_General_CI_AS;
GO
USE TelcoChurnDW;
GO

-- ============================================================
--  SECTION 1 - DIMENSION TABLES
-- ============================================================

-- ------------------------------------------------------------
--  dim_Date   (pre-built calendar spine 2013-2026)
-- ------------------------------------------------------------
CREATE TABLE dim_Date (
    DateSK          INT          NOT NULL,   -- YYYYMMDD surrogate
    FullDate        DATE         NOT NULL,
    [Year]          SMALLINT     NOT NULL,
    Quarter         TINYINT      NOT NULL,
    [Month]         TINYINT      NOT NULL,
    MonthName       NVARCHAR(12) NOT NULL,
    [DayOfMonth]    TINYINT      NOT NULL,
    DayOfWeekNum    TINYINT      NOT NULL,   -- 1=Sun … 7=Sat
    DayOfWeekName   NVARCHAR(12) NOT NULL,
    IsWeekend       BIT          NOT NULL,
    CONSTRAINT PK_dim_Date PRIMARY KEY (DateSK)
);
GO

-- ------------------------------------------------------------
--  dim_Customer   (Type-1 SCD: overwrite on change)
-- ------------------------------------------------------------
CREATE TABLE dim_Customer (
    CustomerSK       INT          NOT NULL IDENTITY(1,1),
    CustomerID       NVARCHAR(10) NOT NULL,   -- natural / business key
    Gender           NVARCHAR(10) NOT NULL,
    IsSeniorCitizen  BIT          NOT NULL,
    HasPartner       BIT          NOT NULL,
    HasDependents    BIT          NOT NULL,
    EffectiveDate    DATE         NOT NULL DEFAULT CAST(GETDATE() AS DATE),
    CONSTRAINT PK_dim_Customer    PRIMARY KEY (CustomerSK),
    CONSTRAINT UQ_dim_Customer_ID UNIQUE      (CustomerID)
);
GO

-- ------------------------------------------------------------
--  dim_PhoneService   (3 possible combinations)
-- ------------------------------------------------------------
CREATE TABLE dim_PhoneService (
    PhoneServiceSK   INT          NOT NULL IDENTITY(1,1),
    HasPhoneService  BIT          NOT NULL,
    HasMultipleLines BIT          NULL,    -- NULL = no phone service
    ServiceProfile   NVARCHAR(40) NOT NULL,  -- human-readable label
    CONSTRAINT PK_dim_PhoneService PRIMARY KEY (PhoneServiceSK)
);
GO

-- ------------------------------------------------------------
--  dim_InternetService   (distinct add-on combos from source data)
-- ------------------------------------------------------------
CREATE TABLE dim_InternetService (
    InternetServiceSK   INT          NOT NULL IDENTITY(1,1),
    InternetServiceType NVARCHAR(20) NOT NULL,  -- 'DSL','Fiber optic','None'
    HasOnlineSecurity   BIT          NULL,
    HasOnlineBackup     BIT          NULL,
    HasDeviceProtection BIT          NULL,
    HasTechSupport      BIT          NULL,
    HasStreamingTV      BIT          NULL,
    HasStreamingMovies  BIT          NULL,
    AddOnCount          TINYINT      NOT NULL,   -- derived: sum of add-ons
    ServiceProfile      NVARCHAR(80) NOT NULL,   -- concise readable label
    CONSTRAINT PK_dim_InternetService PRIMARY KEY (InternetServiceSK)
);
GO

-- ------------------------------------------------------------
--  dim_Contract
-- ------------------------------------------------------------
CREATE TABLE dim_Contract (
    ContractSK       INT          NOT NULL IDENTITY(1,1),
    ContractType     NVARCHAR(30) NOT NULL,
    IsPaperless      BIT          NOT NULL,
    BillingProfile   NVARCHAR(50) NOT NULL,
    CONSTRAINT PK_dim_Contract PRIMARY KEY (ContractSK)
);
GO

-- ------------------------------------------------------------
--  dim_PaymentMethod
-- ------------------------------------------------------------
CREATE TABLE dim_PaymentMethod (
    PaymentMethodSK  INT          NOT NULL IDENTITY(1,1),
    MethodName       NVARCHAR(40) NOT NULL,
    IsAutomatic      BIT          NOT NULL,
    MethodCategory   NVARCHAR(20) NOT NULL,  -- 'Electronic','Paper','Bank'
    CONSTRAINT PK_dim_PaymentMethod PRIMARY KEY (PaymentMethodSK)
);
GO

-- ============================================================
--  SECTION 2 - FACT TABLE
-- ============================================================
CREATE TABLE fact_CustomerSnapshot (
    SnapshotSK          BIGINT        NOT NULL IDENTITY(1,1),
    -- Foreign Keys to Dimensions
    CustomerSK          INT           NOT NULL,
    PhoneServiceSK      INT           NOT NULL,
    InternetServiceSK   INT           NOT NULL,
    ContractSK          INT           NOT NULL,
    PaymentMethodSK     INT           NOT NULL,
    SnapshotDateSK      INT           NOT NULL,
    -- Measures
    Tenure              SMALLINT      NOT NULL,
    MonthlyCharges      DECIMAL(8,2)  NOT NULL,
    TotalCharges        DECIMAL(10,2) NULL,
    -- Degenerate Dimension (stored directly - no lookup needed)
    HasChurned          BIT           NOT NULL,
    -- Derived Measures (pre-computed for BI performance)
    AnnualizedCharges   DECIMAL(10,2) NOT NULL,   -- MonthlyCharges * 12
    LifetimeValue       AS (CAST(TotalCharges AS DECIMAL(12,2))),
    CONSTRAINT PK_fact_CustomerSnapshot PRIMARY KEY (SnapshotSK),
    CONSTRAINT FK_fact_Customer         FOREIGN KEY (CustomerSK)
        REFERENCES dim_Customer (CustomerSK),
    CONSTRAINT FK_fact_PhoneService     FOREIGN KEY (PhoneServiceSK)
        REFERENCES dim_PhoneService (PhoneServiceSK),
    CONSTRAINT FK_fact_InternetService  FOREIGN KEY (InternetServiceSK)
        REFERENCES dim_InternetService (InternetServiceSK),
    CONSTRAINT FK_fact_Contract         FOREIGN KEY (ContractSK)
        REFERENCES dim_Contract (ContractSK),
    CONSTRAINT FK_fact_PaymentMethod    FOREIGN KEY (PaymentMethodSK)
        REFERENCES dim_PaymentMethod (PaymentMethodSK),
    CONSTRAINT FK_fact_Date             FOREIGN KEY (SnapshotDateSK)
        REFERENCES dim_Date (DateSK)
);
GO

-- ============================================================
--  SECTION 3 - INDEXES (BI-optimised)
-- ============================================================
CREATE INDEX IX_fact_CustomerSK        ON fact_CustomerSnapshot (CustomerSK);
CREATE INDEX IX_fact_PhoneServiceSK    ON fact_CustomerSnapshot (PhoneServiceSK);
CREATE INDEX IX_fact_InternetServiceSK ON fact_CustomerSnapshot (InternetServiceSK);
CREATE INDEX IX_fact_ContractSK        ON fact_CustomerSnapshot (ContractSK);
CREATE INDEX IX_fact_PaymentMethodSK   ON fact_CustomerSnapshot (PaymentMethodSK);
CREATE INDEX IX_fact_DateSK            ON fact_CustomerSnapshot (SnapshotDateSK);
CREATE INDEX IX_fact_HasChurned        ON fact_CustomerSnapshot (HasChurned);
CREATE INDEX IX_fact_Tenure            ON fact_CustomerSnapshot (Tenure);
GO

