-- ============================================================
--  SECTION 6 - SAMPLE ANALYTICAL VIEWS
-- ============================================================

-- Churn rate by contract type
CREATE VIEW vw_ChurnByContract AS
SELECT
    dc.ContractType,
    dc.IsPaperless,
    COUNT(*)                                          AS TotalCustomers,
    SUM(CAST(f.HasChurned AS INT))                    AS ChurnedCustomers,
    CAST(SUM(CAST(f.HasChurned AS INT)) * 100.0
         / COUNT(*) AS DECIMAL(5,2))                  AS ChurnRatePct,
    AVG(f.MonthlyCharges)                             AS AvgMonthlyCharges,
    AVG(f.Tenure)                                     AS AvgTenureMonths
FROM  fact_CustomerSnapshot f
JOIN  dim_Contract           dc ON dc.ContractSK = f.ContractSK
GROUP BY dc.ContractType, dc.IsPaperless;
GO

-- Churn rate by internet service profile
CREATE VIEW vw_ChurnByInternetService AS
SELECT
    di.InternetServiceType,
    di.AddOnCount,
    COUNT(*)                                          AS TotalCustomers,
    SUM(CAST(f.HasChurned AS INT))                    AS ChurnedCustomers,
    CAST(SUM(CAST(f.HasChurned AS INT)) * 100.0
         / COUNT(*) AS DECIMAL(5,2))                  AS ChurnRatePct,
    AVG(f.MonthlyCharges)                             AS AvgMonthlyCharges
FROM  fact_CustomerSnapshot   f
JOIN  dim_InternetService     di ON di.InternetServiceSK = f.InternetServiceSK
GROUP BY di.InternetServiceType, di.AddOnCount;
GO

-- Customer lifetime value segmentation
CREATE VIEW vw_CustomerLTV AS
SELECT
    dc.CustomerID,
    dc.Gender,
    dc.IsSeniorCitizen,
    f.Tenure,
    f.MonthlyCharges,
    f.TotalCharges,
    f.AnnualizedCharges,
    f.HasChurned,
    CASE
        WHEN f.TotalCharges >= 5000 THEN 'High Value'
        WHEN f.TotalCharges >= 2000 THEN 'Mid Value'
        ELSE 'Low Value'
    END AS LTVSegment
FROM  fact_CustomerSnapshot f
JOIN  dim_Customer          dc ON dc.CustomerSK = f.CustomerSK;
GO

